nginx_config:
daemon off;
master_process on;
worker_processes 2;
pid /tmp/aegisx-bench-aoumi4oo/nginx.pid;
error_log /tmp/aegisx-bench-aoumi4oo/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-aoumi4oo/body;
    proxy_temp_path /tmp/aegisx-bench-aoumi4oo/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 10.42.1.40:3900; keepalive 256; }
    server {
        listen 10.42.1.113:38079 ssl http2 reuseport;
        ssl_certificate /tmp/aegisx-bench-aoumi4oo/cert.pem;
        ssl_certificate_key /tmp/aegisx-bench-aoumi4oo/key.pem;
        ssl_protocols TLSv1.2 TLSv1.3;
        ssl_session_cache shared:SSL:10m;
        ssl_session_tickets on;
        http2_max_concurrent_streams 256;
        location / {
            root /tmp/aegisx-bench-aoumi4oo/site;
            open_file_cache max=1000 inactive=60s;
            open_file_cache_valid 1s;
        }
    }
}
